/**
 * Writes GRAPHICS.md: every graphic the project spreads still need, with its
 * file name. Run with: npx tsx scripts/graphics-checklist.ts
 */
import fs from "node:fs";
import path from "node:path";
import { projects } from "../src/content/projects";
import { getSpread, SECTIONS, type Figure } from "../src/content/spreads";

const EXTS = ["webp", "png", "jpg", "jpeg", "svg", "gif"];
const has = (slug: string, id: string) =>
  EXTS.some((e) => fs.existsSync(path.join("public", "work", slug, `${id}.${e}`)));

const out: string[] = [
  "# Graphics checklist",
  "",
  "Generated by `npx tsx scripts/graphics-checklist.ts`. Save each file at the path shown",
  "(.webp, .png, .jpg, .svg or .gif) and it replaces the placeholder on the next build.",
  "Charts marked **needs numbers** can also be built in the theme: send the data instead.",
  "",
];
let todo = 0;
for (const p of [...projects].sort((a, b) => a.number - b.number)) {
  const s = getSpread(p.slug);
  if (!s) continue;
  const figs: [string, Figure][] = [
    ...SECTIONS.flatMap((k) => (s[k.key].figures ?? []).map((f) => [k.label, f] as [string, Figure])),
    ...(s.results ?? []).map((f) => ["Results", f] as [string, Figure]),
  ];
  const graphics = figs.filter(([, f]) => f.kind === "graphic");
  if (!graphics.length) continue;
  out.push(`## W—${String(p.number).padStart(2, "0")} ${p.title}`, "");
  for (const [where, f] of graphics) {
    if (f.kind !== "graphic") continue;
    const done = has(p.slug, f.id);
    if (!done) todo++;
    out.push(
      `- [${done ? "x" : " "}] **${f.id} · ${f.title}**${f.chart ? " (chart, needs numbers)" : ""} — ${where}, ${f.ratio ?? "landscape"}`,
      `  ${f.note}`,
      `  \`public/work/${p.slug}/${f.id}.webp\``,
    );
  }
  out.push("");
}
out.splice(6, 0, `**${todo} still to make.**`, "");
fs.writeFileSync("GRAPHICS.md", out.join("\n"));
console.log(`GRAPHICS.md written: ${todo} to make`);
